/**
 * Anthropic Messages API: request projection from Nexus history and assembly of streamed/non-streamed responses.
 *
 * Tool calls are emitted only from complete tool_use blocks of a response that reached message_stop; a stream that
 * ends earlier is "incomplete" and none of its calls run. Signed thinking blocks are kept as provider_state owned by
 * "anthropic:<model>" and replayed only to that owner, and only when extended thinking is enabled for the request.
 */
import type { ChatMessage, ToolCall } from "../types.js";
import type { UsageReport } from "../usage.js";
import {
  argumentsObject,
  num,
  ownedState,
  ProviderStreamError,
  stateDigest,
  textOf,
  wireToolId,
  type NativeFinish,
  type NativeRequest,
  type NativeRequestInput,
  type NativeResult,
  type StreamParser,
} from "./common.js";

type Block = Record<string, any>;
interface Turn { role: "user" | "assistant"; content: Block[] }

function userBlocks(content: ChatMessage["content"]): Block[] {
  if (!Array.isArray(content)) {
    const t = textOf(content);
    return t ? [{ type: "text", text: t }] : [];
  }
  const out: Block[] = [];
  for (const p of content as any[]) {
    if (typeof p === "string") out.push({ type: "text", text: p });
    else if (p?.type === "text" && p.text) out.push({ type: "text", text: p.text });
    else if (p?.type === "image_url" && typeof p.image_url?.url === "string") {
      const m = /^data:([^;]+);base64,(.*)$/s.exec(p.image_url.url);
      out.push(m ? { type: "image", source: { type: "base64", media_type: m[1], data: m[2] } } : { type: "image", source: { type: "url", url: p.image_url.url } });
    }
  }
  return out;
}

/** Thinking is replayable only when the trailing assistant tool turn carries this owner's intact signed thinking. */
function trailingToolTurnHasThinking(messages: ChatMessage[], owner: string): boolean {
  for (let i = messages.length - 1; i >= 0; i--) {
    const m = messages[i];
    if (m.role === "tool") continue;
    if (m.role === "assistant" && m.tool_calls?.length) return Boolean(ownedState(m, owner)?.length);
    return true; // not inside a tool loop: thinking may start fresh
  }
  return true;
}

export function buildAnthropicRequest(input: NativeRequestInput): NativeRequest {
  const thinking = input.thinkingBudget !== undefined && trailingToolTurnHasThinking(input.messages, input.owner);
  const systemParts: string[] = [];
  const turns: Turn[] = [];
  let droppedState = 0;
  let seenNonSystem = false;
  const push = (role: Turn["role"], blocks: Block[]) => {
    if (!blocks.length) return;
    const last = turns[turns.length - 1];
    if (last && last.role === role) last.content.push(...blocks);
    else turns.push({ role, content: blocks });
  };
  for (const m of input.messages) {
    if (m.role === "system") {
      const t = textOf(m.content);
      if (!seenNonSystem) systemParts.push(t);
      else if (t) push("user", [{ type: "text", text: `[System notice]\n${t}` }]);
      continue;
    }
    seenNonSystem = true;
    if (m.role === "user") push("user", userBlocks(m.content));
    else if (m.role === "tool") {
      const content = typeof m.content === "string" ? m.content : JSON.stringify(m.content ?? "");
      push("user", [{ type: "tool_result", tool_use_id: wireToolId(m.tool_call_id ?? ""), content: content || "(no output)" }]);
    } else {
      const blocks: Block[] = [];
      const owned = ownedState(m, input.owner);
      if (m.provider_state && !owned) droppedState++;
      if (thinking && owned) blocks.push(...owned);
      const t = textOf(m.content);
      if (t.trim()) blocks.push({ type: "text", text: t });
      for (const tc of m.tool_calls ?? []) {
        blocks.push({ type: "tool_use", id: wireToolId(tc.id), name: tc.function.name, input: argumentsObject(tc.function.arguments) });
      }
      push("assistant", blocks.length ? blocks : [{ type: "text", text: "(no content)" }]);
    }
  }
  if (turns[0]?.role !== "user") turns.unshift({ role: "user", content: [{ type: "text", text: "(continue)" }] });

  const body: Record<string, unknown> = {
    model: input.model,
    max_tokens: input.maxOutputTokens,
    messages: turns,
    stream: input.stream,
  };
  const system = systemParts.filter(Boolean).join("\n\n");
  if (system) body.system = system;
  if (input.tools.length) {
    body.tools = input.tools.map((t) => ({ name: t.function.name, description: t.function.description, input_schema: t.function.parameters }));
  }
  if (thinking) {
    // Extended thinking requires max_tokens above the budget and does not accept a custom temperature.
    const budget = Math.max(1024, Math.min(input.thinkingBudget!, input.maxOutputTokens - 1024));
    body.thinking = { type: "enabled", budget_tokens: budget };
    if (input.maxOutputTokens <= budget) body.max_tokens = budget + 1024;
  } else if (input.temperature !== undefined) {
    body.temperature = Math.min(1, Math.max(0, input.temperature));
  }
  return { path: "/messages", body, droppedState };
}

function finishOf(stop: string | undefined, hasTools: boolean): NativeFinish {
  if (stop === "max_tokens" || stop === "model_context_window_exceeded") return "length";
  if (stop === "refusal") return "refusal";
  if (stop === "tool_use" || hasTools) return "tool_calls";
  return "stop";
}

function usageOf(u: any, prev: UsageReport = {}): UsageReport {
  if (!u || typeof u !== "object") return prev;
/**
 * Inference usage ledger: one receipt per provider-connection request (main agent, planner/coder, subagents and
 * auxiliary calls all share the process-wide ledger), and the spending limits checked before each cloud request.
 *
 * Receipts never hold credentials, headers or request bodies. Usage is what the provider reported; cost is recorded
 * only when the provider reported it (OpenRouter) and is otherwise "unknown" — never estimated from a price table.
 * Limits are enforced on reported/reserved figures and are not a guarantee of the provider's final invoice.
 */
import { snapshotModel } from "./core/models_snapshot.js";
import * as fs from "node:fs";
import * as path from "node:path";
import { ensurePrivateDir, appendPrivateFile } from "./core/durable_file.js";
import { ensureSelfIgnore } from "./core/git_exclude.js";

export interface UsageReport {
  inputTokens?: number;
  outputTokens?: number;
  cachedInputTokens?: number;
  cacheWriteTokens?: number;
  reasoningTokens?: number;
  /** Provider-reported cost in USD. */
  costUsd?: number;
}

export interface InferenceReceipt {
  at: string;
  requestId: string;
  role: string;
  providerId: string;
  /** The model the operator selected and the model the provider reports having used (may differ, e.g. OpenRouter routing). */
  selectedModel: string;
  effectiveModel?: string;
  endpointOrigin: string;
  protocol: string;
  disclosure: "local" | "cloud";
  origin_class?: "local" | "cloud" | string;
  executions?: number;
  outcome: "completed" | "failed" | "aborted";
  failureKind?: string;
  providerRequestId?: string;
  usage?: UsageReport;
  /** "provider": usage came from the provider; "uncertain": the request may have been billed but no usage arrived. */
  usageConfidence: "provider" | "uncertain" | "none";
  costConfidence: "provider-reported" | "unknown";
}

export interface SpendingLimits {
  maxRequests?: number;
  maxTokens?: number;
  maxCostUsd?: number;
}

export function spendingLimitsFromEnv(env: NodeJS.ProcessEnv = process.env): SpendingLimits {
  const num = (k: string) => {
    const v = Number(env[k]);
    return Number.isFinite(v) && v > 0 ? v : undefined;
  };
  return { maxRequests: num("NEXUS_CLOUD_MAX_REQUESTS"), maxTokens: num("NEXUS_CLOUD_MAX_TOKENS"), maxCostUsd: num("NEXUS_CLOUD_MAX_COST_USD") };
}

/**
 * Limits per provider id, from NEXUS_CLOUD_LIMITS, a JSON object such as
 * `{"openrouter":{"maxCostUsd":5,"maxTokens":2000000},"groq":{"maxRequests":200}}`. They apply on top of the global
 * NEXUS_CLOUD_MAX_* limits. A value that does not parse is returned as `error`, and every cloud request is then refused:
 * a limit that silently fails to apply is worse than none.
 */
export function providerLimitsFromEnv(env: NodeJS.ProcessEnv = process.env): { limits: Record<string, SpendingLimits>; error?: string } {
  const raw = env.NEXUS_CLOUD_LIMITS;
  if (raw === undefined || raw.trim() === "") return { limits: {} };
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("not an object");
    const limits: Record<string, SpendingLimits> = {};
    for (const [id, value] of Object.entries(parsed as Record<string, unknown>)) {
      if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error(`${id}: not an object`);
      const out: SpendingLimits = {};
      for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
        if (k !== "maxRequests" && k !== "maxTokens" && k !== "maxCostUsd") throw new Error(`${id}: unknown limit ${k}`);
        if (typeof v !== "number" || !Number.isFinite(v) || v <= 0) throw new Error(`${id}.${k}: must be a positive number`);
        out[k] = v;
      }
      limits[id] = out;
    }
    return { limits };
  } catch (err) {
    return { limits: {}, error: `NEXUS_CLOUD_LIMITS is not valid (${err instanceof Error ? err.message : "unparseable"})` };
  }
}

/** USD for one request at the snapshot's price (per million tokens) for the model it used; undefined when no price is known. */
function snapshotCost(providerId: string, model: string, usage: UsageReport | undefined): number | undefined {
  const price = snapshotModel(providerId, model)?.price;
  if (!price || !usage) return undefined;
  return ((usage.inputTokens ?? 0) * price.input + (usage.outputTokens ?? 0) * price.output) / 1_000_000;
}

export interface UsageTotals {
  requests: number;
  inputTokens: number;
  outputTokens: number;
  costUsd: number;
  /** Requests whose cost the provider did not report. */
  unpricedRequests: number;
  /** Requests that may have been billed without reported usage (failed mid-stream, timed out). */
  uncertainRequests: number;
  /** Requests priced from the models snapshot instead of by the provider (per-provider totals only). */
  estimatedRequests: number;
}

export class UsageLedger {
  private static instance?: UsageLedger;
  static global(): UsageLedger {
    return (UsageLedger.instance ??= new UsageLedger());
  }
  /** Tests isolate ledgers. */
  static resetGlobal(): void {
    UsageLedger.instance = undefined;
  }

  private receipts: InferenceReceipt[] = [];
/** The wire protocols a connection can speak. Adding one is a module here plus an entry in WIRE_PROTOCOLS. */
import type { WireProtocol } from "../providers.js";
import { anthropicStreamParser, buildAnthropicRequest, parseAnthropicResponse } from "./anthropic.js";
import { buildGeminiRequest, geminiStreamParser, parseGeminiResponse } from "./gemini.js";
